function validate([nums, low, high]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 20000) return 'nums needs 1 to 20000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 20000)) return 'Each value of nums is an integer from 1 to 20000.';
  if (!Number.isInteger(low) || !Number.isInteger(high) || low < 1 || high > 20000 || low > high) return 'Need 1 <= low <= high <= 20000.';
  return null;
}

