function countPairs(nums, low, high) {
  const BITS = 15;
  const root = { child: [null, null], count: 0 };

  const countBelow = (value, limit) => {
    let node = root;
    let total = 0;
    for (let bit = BITS - 1; bit >= 0 && node !== null; bit--) {
      const valueBit = (value >> bit) & 1;
      const limitBit = (limit >> bit) & 1;
      if (limitBit === 1) {
        const same = node.child[valueBit];
        if (same !== null) total += same.count;
        node = node.child[valueBit ^ 1];
      } else {
        node = node.child[valueBit];
      }
    }
    return total;
  };

  let pairs = 0;
  for (const value of nums) {
    pairs += countBelow(value, high + 1) - countBelow(value, low);
    let node = root;
    for (let bit = BITS - 1; bit >= 0; bit--) {
      const valueBit = (value >> bit) & 1;
      if (node.child[valueBit] === null) {
        node.child[valueBit] = { child: [null, null], count: 0 };
      }
      node = node.child[valueBit];
      node.count++;
    }
  }
  return pairs;
}

