function countPairs(nums, low, high) {
  let total = 0;
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++) {
      const x = nums[i] ^ nums[j];
      if (x >= low && x <= high) total++;
    }
  return total;
}

